# The trigger functions revert to their 0018 form on downgrade by re-running
# 0018's statements (they are CREATE OR REPLACE).
_DOWN = ['ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS fk_ai_executions_provider_account', 'ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS fk_ai_executions_ai_job', 'ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS ck_ai_executions_parent_type_known', 'ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS ck_ai_executions_arc_cardinality', 'ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS ck_ai_executions_parent_type_matches', 'ALTER TABLE ai_executions DROP CONSTRAINT IF EXISTS ck_ai_executions_attempt_reason', 'DROP INDEX IF EXISTS ix_ai_executions_provider_account_id', 'DROP INDEX IF EXISTS ix_ai_executions_ai_job_id', 'ALTER TABLE ai_executions DROP COLUMN IF EXISTS stop_reason', 'ALTER TABLE ai_executions DROP COLUMN IF EXISTS provider_account_id', 'ALTER TABLE ai_executions DROP COLUMN IF EXISTS ai_job_id', "ALTER TABLE ai_executions ADD CONSTRAINT ck_ai_executions_parent_type_known CHECK (parent_type IN ('visibility_run'))", 'ALTER TABLE ai_executions ADD CONSTRAINT ck_ai_executions_arc_cardinality CHECK (num_nonnulls(visibility_run_id) <= 1)', "ALTER TABLE ai_executions ADD CONSTRAINT ck_ai_executions_parent_type_matches CHECK (visibility_run_id IS NULL OR parent_type = 'visibility_run')", "ALTER TABLE ai_executions ADD CONSTRAINT ck_ai_executions_attempt_reason CHECK (attempt_reason IS NULL OR attempt_reason IN ('retry', 'manual_retry', 'provider_fallback', 'model_fallback'))", 'DROP TABLE IF EXISTS ai_job_items', 'DROP TABLE IF EXISTS ai_jobs', 'DROP TABLE IF EXISTS knowledge_keywords', 'DROP TABLE IF EXISTS ai_discovery_entries', 'DROP TABLE IF EXISTS ai_working_memory', 'DROP TABLE IF EXISTS ai_routing_decisions', 'DROP TABLE IF EXISTS ai_routing_steps', 'DROP TABLE IF EXISTS ai_routing_policies', 'DROP TABLE IF EXISTS ai_health_events', 'DROP TABLE IF EXISTS ai_models', 'DROP TABLE IF EXISTS ai_provider_accounts', 'DROP TABLE IF EXISTS ai_providers']


def upgrade() -> None:
    for stmt in _UP:
        op.execute(sa.text(stmt))


def downgrade() -> None:
    for stmt in _DOWN:
        op.execute(sa.text(stmt))
    import importlib.util, pathlib
    spec = importlib.util.spec_from_file_location(
        "m0018", pathlib.Path(__file__).with_name("0018_phase17_execution_immutability.py"))
    m0018 = importlib.util.module_from_spec(spec); spec.loader.exec_module(m0018)
    for stmt in m0018._STATEMENTS:
        op.execute(sa.text(stmt))
